import json, pika

ch = pika.BlockingConnection(pika.ConnectionParameters("localhost")).channel()
ch.queue_declare(queue="emails", durable=True)
ch.basic_qos(prefetch_count=10)

def send_email(msg): print("sending to", msg["to"])

def on_message(channel, method, props, body):
    try:
        msg = json.loads(body)
    except ValueError:
        channel.basic_reject(method.delivery_tag, requeue=False)   # poison: drop/DLX
        return
    try:
        send_email(msg)
        channel.basic_ack(method.delivery_tag)                    # only after success
    except ConnectionError:
        channel.basic_nack(method.delivery_tag, requeue=True)     # transient: retry
    if method.redelivered:
        print("this message was delivered before")

ch.basic_consume(queue="emails", on_message_callback=on_message)  # manual acks
ch.start_consuming()
